import fs from 'fs';
import os from 'os';
import path from 'path';
import {
  selectedOperatingSystemServices,
  type HostCommandService,
} from '../services/OperatingSystemServices';


const LEGACY_MCP_SERVER_NAMES = ['rivet', 'rivet-local'] as const;
const HOST_CLI_INSPECTION_TIMEOUT_MS = 5_000;

export type LegacyCleanupResult = { changed: boolean };

export const claudeDesktopConfigPath = (
  homeDir: string = os.homedir(),
): string => {
  if (process.platform === 'darwin') {
    return path.join(
      homeDir,
      'Library',
      'Application Support',
      'Claude',
      'claude_desktop_config.json',
    );
  }
  if (process.platform === 'win32') {
    const appData =
      process.env.APPDATA ?? path.join(homeDir, 'AppData', 'Roaming');
    return path.join(appData, 'Claude', 'claude_desktop_config.json');
  }
  return path.join(homeDir, '.config', 'Claude', 'claude_desktop_config.json');
};

export const cursorMcpConfigPath = (homeDir: string = os.homedir()): string =>
  path.join(homeDir, '.cursor', 'mcp.json');

export const isServeRegistration = (entry: unknown): boolean => {
  if (entry === null || typeof entry !== 'object') return false;
  const args = (entry as { args?: unknown }).args;
  if (!Array.isArray(args)) return false;
  const joined = args.map(String).join(' ');
  return /(^|\s)mcp serve(\s|$)/.test(`${joined} `);
};

const removeMcpServerEntries = (configPath: string): LegacyCleanupResult => {
  if (!fs.existsSync(configPath)) return { changed: false };
  let parsed: unknown;
  try {
    parsed = JSON.parse(fs.readFileSync(configPath, 'utf8'));
  } catch {
    return { changed: false };
  }
  if (parsed === null || typeof parsed !== 'object' || Array.isArray(parsed)) {
    return { changed: false };
  }
  const config = parsed as { mcpServers?: Record<string, unknown> };
  if (!config.mcpServers || typeof config.mcpServers !== 'object') {
    return { changed: false };
  }
  const mcpServers = config.mcpServers;
  const present = LEGACY_MCP_SERVER_NAMES.filter(
    (name) =>
      name in mcpServers &&
      !isServeRegistration(mcpServers[name]),
  );
  if (present.length === 0) return { changed: false };
  for (const name of present) delete config.mcpServers[name];
  fs.writeFileSync(configPath, JSON.stringify(config, null, 2) + '\n', 'utf8');
  return { changed: true };
};

export const cleanupCursorLegacyMcp = (
  homeDir: string = os.homedir(),
): LegacyCleanupResult => removeMcpServerEntries(cursorMcpConfigPath(homeDir));

export const cleanupClaudeDesktopLegacyMcp = (
  homeDir: string = os.homedir(),
): LegacyCleanupResult =>
  removeMcpServerEntries(claudeDesktopConfigPath(homeDir));

type HostCliRegistration = 'serve' | 'legacy' | 'unknown';

const inspectHostCliRegistration = (
  bin: string,
  executeHostCommand: HostCommandService['executeSync'],
): HostCliRegistration => {
  try {
    const output = executeHostCommand(
      { executable: bin, args: ['mcp', 'get', 'rivet'] },
      {
        stdio: 'pipe',
        timeout: HOST_CLI_INSPECTION_TIMEOUT_MS,
      },
    ).toString();
    return /mcp serve/.test(output) ? 'serve' : 'legacy';
  } catch {
    return 'unknown';
  }
};

const cleanupHostCliLegacyMcp = (
  bin: string,
  executeHostCommand: HostCommandService['executeSync'],
): LegacyCleanupResult => {
  if (inspectHostCliRegistration(bin, executeHostCommand) !== 'legacy') {
    return { changed: false };
  }
  try {
    executeHostCommand(
      { executable: bin, args: ['mcp', 'remove', 'rivet'] },
      {
        stdio: 'pipe',
        timeout: HOST_CLI_INSPECTION_TIMEOUT_MS,
      },
    );
    return { changed: true };
  } catch {
    return { changed: false };
  }
};

type HostCliLegacyCleanupOptions = {
  bin?: string;
  executeHostCommand?: HostCommandService['executeSync'];
};

export const cleanupClaudeLegacyMcp = (
  options: HostCliLegacyCleanupOptions = {},
): LegacyCleanupResult =>
  cleanupHostCliLegacyMcp(
    options.bin ?? 'claude',
    options.executeHostCommand ??
      selectedOperatingSystemServices.hostCommands.executeSync,
  );

export const cleanupCodexLegacyMcp = (
  options: HostCliLegacyCleanupOptions = {},
): LegacyCleanupResult =>
  cleanupHostCliLegacyMcp(
    options.bin ?? 'codex',
    options.executeHostCommand ??
      selectedOperatingSystemServices.hostCommands.executeSync,
  );

export type RemovedMcpCleanupResult = LegacyCleanupResult & {
  targets: string[];
};

export const cleanupRemovedMcpRegistrations = (args: {
  editor?: string;
  homeDir?: string;
  executeHostCommand?: HostCommandService['executeSync'];
}): RemovedMcpCleanupResult => {
  const editor = args.editor?.trim().toLowerCase();
  const homeDir = args.homeDir ?? os.homedir();
  const executeHostCommand =
    args.executeHostCommand ??
    selectedOperatingSystemServices.hostCommands.executeSync;
  const targets: string[] = [];
  const record = (target: string, result: LegacyCleanupResult): void => {
    if (result.changed) targets.push(target);
  };

  if (editor === 'cursor') {
    record('cursor', cleanupCursorLegacyMcp(homeDir));
  } else if (editor === 'codex') {
    record('codex', cleanupCodexLegacyMcp({ executeHostCommand }));
  } else if (editor === 'claude' || editor === 'claude-desktop') {
    record('claude', cleanupClaudeLegacyMcp({ executeHostCommand }));
    record('claude-desktop', cleanupClaudeDesktopLegacyMcp(homeDir));
  } else {
    record('cursor', cleanupCursorLegacyMcp(homeDir));
    record('claude-desktop', cleanupClaudeDesktopLegacyMcp(homeDir));
  }

  return { changed: targets.length > 0, targets };
};
